import os, csv

BASE = os.path.join("storage", "shared", "agency_lab")
CSV_DIR = os.path.join(BASE, "analyses", "csv")
MEANS = os.path.join(CSV_DIR, "transgen_means_v0_1.csv")
OUT  = os.path.join(CSV_DIR, "transgen_means_v0_1_normalized.csv")
DEN  = os.path.join(BASE, "data", "transgen_config", "progressor_max_collective_reward_per_round.csv")

def read_csv(path):
    with open(path, "r", encoding="utf-8", newline="") as f:
        return list(csv.DictReader(f))

def write_csv(path, rows):
    if not rows:
        return
    with open(path, "w", encoding="utf-8", newline="") as f:
        w = csv.DictWriter(f, fieldnames=list(rows[0].keys()))
        w.writeheader(); w.writerows(rows)

def to_float(x):
    try:
        return float(x)
    except Exception:
        return None

def load_denoms(path):
    rows = read_csv(path)
    if not rows:
        return {}
    # Heuristic: find generation and denominator columns
    cols = list(rows[0].keys())
    gen_col = next((c for c in cols if c.lower() in ("generation","gen","g")), cols[0])
    cand = [c for c in cols if "max" in c.lower() and "collective" in c.lower() and "reward" in c.lower() and "round" in c.lower()]
    den_col = cand[0] if cand else (cols[1] if len(cols) > 1 else cols[0])
    out = {}
    for r in rows:
        gi = r.get(gen_col)
        di = to_float(r.get(den_col))
        if gi is None or di is None:
            continue
        try:
            out[int(float(gi))] = di
        except Exception:
            pass
    return out

def main():
    if not (os.path.exists(MEANS) and os.path.exists(DEN)):
        print("WARN missing:", {"means": os.path.exists(MEANS), "denoms": os.path.exists(DEN)})
        return 0
    denom = load_denoms(DEN)
    means = read_csv(MEANS)
    if not means or not denom:
        print("WARN empty inputs:", {"means_rows": len(means), "denoms": len(denom)})
        return 0
    # Identify columns
    cols = list(means[0].keys())
    gen_cols = ["generation","Generation","gen","Gen"]
    trm_col = next((c for c in cols if c.lower()=="total_reward_mean" or ("total" in c.lower() and "reward" in c.lower() and "mean" in c.lower())), None)
    na_col  = next((c for c in cols if c.lower() in ("num_agents","agents","n_agents")), None)

    out = []
    for r in means:
        g_raw = next((r.get(c) for c in gen_cols if r.get(c) not in (None,"")), None)
        if g_raw is None:
            continue
        try:
            g = int(float(g_raw))
        except Exception:
            continue
        trm = to_float(r.get(trm_col)) if trm_col else None
        den = denom.get(g)
        norm = (trm/den) if (trm is not None and den not in (None,0)) else ""
        na_raw = r.get(na_col) if na_col else ""
        pa = ""
        if trm is not None and na_raw not in ("",None):
            try:
                na = float(na_raw)
                if na > 0:
                    pa = trm/na
            except Exception:
                pass
        out.append({
            "generation": g,
            "total_reward_mean": trm if trm is not None else "",
            "normalized_collective_reward_mean": norm,
            "num_agents": na_raw,
            "per_agent_reward_mean": pa if pa != "" else "",
        })
    os.makedirs(CSV_DIR, exist_ok=True)
    write_csv(OUT, out)
    print("WROTE", OUT, "rows=", len(out))
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
